  "appearance_facts": [
    {
      "location": "far left of the plot area, above the 'Product A' label",
      "fact": "The Product A bar is a short, dark red vertical rectangle. Its top edge is positioned below the 10,000 grid line on the y-axis."
    },
    {
      "location": "second from left, above the 'Product E' label",
      "fact": "The Product E bar is the tallest mark on the page, with its top edge aligned exactly with the 80,000 grid line."
    },
    {
      "location": "center, above the 'Product B' label",
      "fact": "The Product B bar is a tall dark red rectangle, with its top edge positioned between the 60,000 and 70,000 grid lines."
    },
    {
      "location": "fourth from left, above the 'Product D' label",
      "fact": "The Product D bar is a tall dark red rectangle, slightly taller than Product B, with its top edge positioned between the 60,000 and 70,000 grid lines."
    },
    {
      "location": "far right, above the 'Product C' label",
      "fact": "The Product C bar is a short dark red rectangle, with its top edge positioned just below the 20,000 grid line."
    },
    {
      "location": "comparing all five bars",
      "fact": "The Product A bar is the shortest mark on the chart, appearing significantly lower than the Product C bar and the three tall central bars."
    }
  ],
  "printed_facts": [
    {
      "location": "top left",
      "fact": "The chart title is 'Units Sold by Product (Weekend Pop-up)'."
    },
    {
      "location": "left vertical axis",
      "fact": "The y-axis is labeled 'Units Sold' and displays numerical ticks from 10,000 to 80,000 in increments of 10,000."
    },
    {
      "location": "bottom horizontal axis",
      "fact": "The x-axis is labeled 'Product' and lists the categories 'Product A', 'Product E', 'Product B', 'Product D', and 'Product C' from left to right."
    }
  ],
  "public_definitions": [
    "The policy table defines '< 4,000 units' as 'Urgent sales intervention level'.",
    "The policy table defines '>= 4,000 and < 9,000 units' as 'Low-demand review queue activation level'.",
    "The policy table defines '< 1,000 units from a decision threshold' as 'Manual sales verification variance band'.",
    "The policy table defines '>= 14,000 and < 22,000 units' as 'Expanded replenishment planning level'.",
    "The policy table defines '>= 22,000 units' as 'Growth allocation review level'."
  ],
  "uncertain": [
    "The exact numerical value of the Product A bar is not printed; it is visually estimated to be below the 10,000 mark.",
    "It is not explicitly stated if the 'decision threshold' for the manual verification band refers to the 4,000 or 9,000 unit boundaries defined in other rows."
  ]
}
